// Reached either straight from `Called by Master Router` (outreach) or from
// `Is New Message?`. In the second case the item we are handed is the dedupe
// guard's HTTP response, not the webhook body -- an HTTP node's output REPLACES
// the item -- so reach back to the webhook node for the real payload.
/* TENANT SCOPE: media lives inside the dealership's own WAHA container and the
 * brand name in an outreach message is the dealership's, not a literal. Both come
 * from Tenant Policy; a media URL with no per-tenant host refuses by name rather
 * than reaching into the shared http://waha:3000 container. */
const _tp = $('Tenant Policy').first().json || {};
const _waha = _tp.tenant_waha || {};
const BRAND = (_tp.tenant_policy && _tp.tenant_policy.brand_name) || null;
const _mediaUrl = (u) => {
  const s = String(u || '');
  if (!s) return null;
  if (!s.includes('localhost:3000')) return s;
  if (!_waha.base_url) throw new Error('BDC_WAHA_MEDIA_HOST_UNRESOLVED: a customer sent media ' +
    'and there is no per-dealership WAHA host to fetch it from. ' + (_waha.refusals || []).join(' | '));
  return s.replace('http://localhost:3000', _waha.base_url);
};

let item = $input.first().json;
if (!item.lead && !item.body && !item.payload) {
  try { item = $('WAHA Webhook (POST)').first().json; } catch (e) { /* outreach path */ }
}

if (item.lead) {
  const lead = item.lead;
  const interest = lead.vehicle_interest || lead.vehicleInterest || lead.message || 'a vehicle';
  let chatId = String(lead.phone || lead.whatsapp || '').trim();
  if (!chatId) return [];
  if (!chatId.includes('@')) chatId = chatId.replace(/[^0-9]/g, '') + '@c.us';
  return [{ json: {
    message: 'INITIAL_OUTREACH: Lead name: ' + (lead.name || 'there') + ', interested in: ' + interest + '. Send them a warm, personalised WhatsApp welcome message introducing ' + (BRAND || 'the dealership') + ' and asking how you can help.',
    sender: chatId,
    lead_email: lead.email || null,
    direction: 'outbound',
    is_voice: false,
    // Outreach is not a WAHA delivery. Give it a unique id so the idempotency
    // guard downstream always lets it through.
    message_id: 'outreach:' + Date.now() + '-' + Math.random().toString(36).slice(2, 10)
  } }];
}

const body = item.body || item;
const payload = body.payload || {};

const event = String(body.event || '');
if (event && event !== 'message') return [];

// Never reply to our own messages -> this is what caused the infinite loop
if (payload.fromMe === true) return [];

// Drop groups, status broadcasts and newsletters.
// NOTE: '@lid' is NOT filtered - WhatsApp now uses LID addressing for real
// 1:1 customer chats, so blocking it silently drops genuine messages.
const from = String(payload.from || '');
if (!from || from.endsWith('@g.us') || from.startsWith('status@') || from.endsWith('@newsletter')) return [];

// A customer sending their Emirates ID sends an IMAGE with no caption. The old
// code did `if (!text) return []` and silently dropped it - the KYC workflow was
// never reachable from WhatsApp at all. Detect media and carry it forward.
const text = typeof payload.body === 'string' ? payload.body.trim() : '';
const media = payload.media || {};
const isImage = payload.hasMedia === true && String(media.mimetype || '').startsWith('image/');

// WAHA hands back its own file URL as localhost:3000 - that is localhost *inside
// the WAHA container*. n8n must fetch it over the docker network instead.
const documentUrl = isImage
  ? _mediaUrl(media.url)
  : null;

// 30 Aug 2026: VOICE NOTES (PTT). Before this, a voice note had no text and a
// non-image mimetype, so `if (!text && !isImage) return []` below dropped the
// execution HERE, at node 6 of ~16. Nothing downstream ever ran, which is why
// customers who spoke instead of typing got total silence.
//
// Branch on the EXISTENCE of _data.Message.audioMessage, not on Info.MediaType:
// MediaType is 'ptt' for a held-mic recording but 'audio' for a forwarded audio
// file, and some GOWS builds omit it entirely. audioMessage is present for both.
const audioMsg = (payload._data && payload._data.Message && payload._data.Message.audioMessage) || null;
const isVoice = !!audioMsg;
const audioUrl = isVoice
  ? _mediaUrl(media.url)
  : null;
const audioSeconds = isVoice ? Number(audioMsg.seconds || 0) : 0;
const audioMime = isVoice ? String(media.mimetype || audioMsg.mimetype || 'audio/ogg; codecs=opus') : null;

if (!text && !isImage && !isVoice) return [];

// WhatsApp now addresses many 1:1 chats by LID (e.g. 158510264357112@lid), which
// carries NO phone number -- matching a lead on its digits is impossible. The real
// number is in _data.Info.SenderAlt. Keep `sender` as the chat id (replies must go
// back to it) and expose the true number separately for lead matching.
const info = (payload._data && payload._data.Info) || {};
const alt = String(info.SenderAlt || '');
const senderPhone = (alt.includes('@') ? alt.split('@')[0] : alt) ||
                    (from.endsWith('@lid') ? '' : from.split('@')[0]);

// WAHA has delivered the same message three times in one second, repeatedly.
// `payload.id` is the WhatsApp message id and is stable across those duplicates,
// so it is what the idempotency guard downstream claims. Fall back to
// sender+timestamp when WAHA omits it; empty means the guard cannot key on
// anything and will let the message through.
const messageId = String(payload.id || (payload.timestamp ? from + ':' + payload.timestamp : ''));

// The image placeholder must NOT be reused for audio: it contains the word
// 'document', which is in Reply Eligibility's keyword allowlist, and
// `New Lead Worth Scoring?` string-compares against it. Either way this value is
// replaced by the transcript before Resolve Lead Identity emits it.
const placeholder = isImage ? '[Customer sent a document image]' : '[Customer sent a voice note]';

return [{ json: {
  message_id: messageId,
  message: text || placeholder,
  is_document: isImage,
  document_url: documentUrl,
  is_voice: isVoice,
  audio_url: audioUrl,
  audio_seconds: audioSeconds,
  audio_mime: audioMime,
  sender: from,
  sender_phone: senderPhone,
  push_name: info.PushName || null,
  lead_email: null,
  direction: 'inbound'
} }];

// Resolve the WhatsApp chat id back to a real lead so every log row is keyed
// on the lead's EMAIL, not on a raw chat id. Without this the silence detector
// (Phase 6) can never join communication_logs back to the leads table.
//
// Match on sender_phone (the true number pulled from Info.SenderAlt), NOT on the
// chat id -- a LID chat id has no phone digits in it at all.
const ex = $('Extract Message & Sender').first().json;

// 30 Aug 2026: VOICE NOTES. A voice note's words only exist after transcription,
// which runs between `Extract Message & Sender` and this node. Prefer that
// transcript here and nowhere else: EVERY downstream consumer of the customer's
// words reads `message` off THIS node --
//   Reply Eligibility (keyword allowlist), Model Ladder (`message: ctx.message`,
//   which overrides whatever the previous node passed), the AI agent's prompt
//   expression, Skip Duplicate Outreach, New Lead Worth Scoring?,
//   Shape Lead For Router, Log Incoming Message.
// Substituting once, here, is what makes a voice note behave exactly like text.
let voice = null;
try {
  const mt = $('Merge Voice Transcript');
  if (mt && (mt.isExecuted === undefined || mt.isExecuted)) voice = mt.first().json || null;
} catch (e) { voice = null; }
const digits = String(ex.sender_phone || ex.sender || '').replace(/[^0-9]/g, '');
const last9 = digits.slice(-9);

// A lead row is what makes `matched_lead` true, and `matched_lead` is what makes the bot
// answer someone unconditionally. So a wrong number that got written into `leads` by
// mistake would be answered forever. Marking it DISQUALIFIED in the dashboard is the
// reversible way to take it back out of the allowlist -- nothing is deleted.
// TENANT SCOPE: the pre-fix version took $input.all() -- the output of
// `Fetch All Leads` (getAll / returnAll, EVERY lead of EVERY dealership) -- and
// matched on the last 9 digits with no tenant compare. The candidate set now
// arrives from `Fetch Matched Lead`: at most one row, already filtered to this
// dealership twice (inside nexus_lead_for_comm_key(p_tenant) and again as
// tenant_id=eq.<t> on the row fetch). The DISQUALIFIED rule is unchanged --
// marking a wrong number DISQUALIFIED in the dashboard is still how it is taken
// back out of the allowlist, and nothing is deleted.
const tenantId = $('Tenant Context').first().json.tenant_id;
const candidates = $input.all().map(i => i.json)
  .filter(l => l && l.id && l.tenant_id !== undefined ? l.tenant_id === tenantId : !!(l && l.id));
const match = candidates.find(l =>
  String(l.status || '').toUpperCase() !== 'DISQUALIFIED') || null;
if (last9.length !== 9 && !match) { /* nothing to key on; match stays null */ }
return [{ json: {
  message: (voice && voice.message) ? voice.message : ex.message,
  is_document: ex.is_document || false,
  is_voice: !!voice,
  voice_transcribed: voice ? voice.voice_transcribed === true : false,
  voice_transcript: voice ? String(voice.voice_transcript || '') : '',
  voice_language: voice ? (voice.voice_language || null) : null,
  voice_seconds: voice ? Number(voice.voice_seconds || 0) : 0,
  voice_drop_reason: voice ? String(voice.voice_drop_reason || '') : '',
  document_url: ex.document_url || null,
  sender: ex.sender,
  sender_phone: ex.sender_phone || null,
  push_name: ex.push_name || null,
  direction: ex.direction,
  lead_email: ex.lead_email || (match ? match.email : null),
  lead_name: match ? match.name : (ex.push_name || null),
  matched_lead: !!match,
  tenant_id: tenantId
} }];

// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The previous ladder had a PAID gemini tier plus
// two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free is
// 404 free-tier-discontinued), which is why all 4 tiers failed on live traffic.
//
// 29 Aug 2026: REMOVED tier 1, 'nvidia/nemotron-3-ultra-550b-a55b:free'. It failed
// on BOTH agents inside the same real run -- exec 6251 here (46.5s wasted) and
// exec 6253 in the Master Router (45.8s) -- with 'Cannot read properties of
// undefined (reading \'message\')'. The ladder escalated correctly each time, so
// this was never a ladder bug: the model is dead, and every inbound message was
// paying ~45s for it before getting a real answer. That run took 87s end to end,
// and at 5 production slots this latency is a direct contributor to concurrency
// exhaustion -- the box hit 6/5 active with a growing queue the same morning.
//
// 30 Aug 2026: groqModel changed from 'llama-3.3-70b-versatile' to
// 'openai/gpt-oss-120b' on every tier. Groq SHUT DOWN llama-3.3-70b-versatile
// for free and developer tiers on 16 Aug 2026 -- their deprecations page names
// openai/gpt-oss-120b as the replacement, their models page now marks the old
// id Enterprise/Contact-Sales, and it has no row at all in the free-tier
// rate-limit table. Because Groq is only the FALLBACK model, it had never
// fired in production, so nothing had surfaced this: the slot would have
// failed for the first time on the day the primary was already down. The
// replacement is production-tier (not preview), free-tier callable, and
// supports OpenAI-style tool calling, which the ladder requires.
// Free-tier ceiling to remember: 30 RPM / 1K RPD / 8K TPM / 200K TPD -- the
// 8K tokens-per-minute limit binds well before the request limit does.
const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',                groqModel: GROQ_FALLBACK }
];
// 'Log Incoming Message' is a Supabase insert that returns an EMPTY body, so
// $input here carries no message and the Agent failed with "No prompt specified"
// on every tier -- which looked like a model outage but never was. Pull the
// conversation context straight from 'Resolve Lead Identity' and re-attach it on
// every retry, so the prompt survives the ladder loop.
let ctx = {};
try { ctx = $('Resolve Lead Identity').first().json || {}; } catch (e) { ctx = {}; }

const prev = $input.first().json;
const attempt = Number(prev.__attempt ?? -1) + 1;
if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed. Tried: ' + TIERS.map(t=>t.orModel).join(', '));
}
if (!ctx.message) {
  throw new Error('No message found on Resolve Lead Identity output - cannot prompt the agent.');
}
return [{ json: { ...ctx, ...prev, message: ctx.message, __attempt: attempt, orModel: TIERS[attempt].orModel, groqModel: TIERS[attempt].groqModel } }];

// Quality gate before anything reaches a real customer on WhatsApp.
// Execution 1414 sent the literal text "The user" -- a leaked fragment of the
// model's internal reasoning. Some free OpenRouter models emit reasoning tokens,
// and the agent passed them straight through to the customer.
const prev = $input.first().json;
let text = String(prev.output ?? '').trim();

// Drop explicit reasoning blocks some models wrap their thinking in.
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '')
           .replace(/<reasoning>[\s\S]*?<\/reasoning>/gi, '')
           .trim();

// Reasoning leaks talk *about* the user in the third person, or are stubs.

// WhatsApp renders none of markdown. Convert what the model still slips through.
text = text.replace(/^\s*\|.*\|\s*$/gm, '')        // table rows
           .replace(/^\s*[-: |]{6,}\s*$/gm, '')       // table separators
           .replace(/\*\*(.+?)\*\*/g, '*$1*')        // **bold** -> *bold*
           .replace(/^#{1,6}\s*/gm, '')                // headings
           .replace(/\n{3,}/g, '\n\n')
           .trim();

const LEAK = /^(the user|okay,? (the|so)|we need to|i should|let'?s (see|think)|analysis|reasoning)\b/i;
const looksLikeLeak = LEAK.test(text);
const tooShort = text.length < 12;

const FALLBACK = "Sorry, I didn't catch that properly. Could you tell me a bit more about what you're looking for?";
const safe = (looksLikeLeak || tooShort) ? FALLBACK : text;

return [{ json: { ...prev, output: safe, guard_blocked: safe !== text, raw_output: text } }];

// Stop a second INITIAL_OUTREACH to a lead we already messaged in the last 24h.
// On 16 Aug the router was posted twice and the customer got two near-identical
// welcome messages 4 minutes apart. Inbound replies are never blocked - only
// proactive outreach.
const ctx = $('Resolve Lead Identity').first().json;
const isOutreach = ctx.direction === 'outbound' ||
                   String(ctx.message || '').startsWith('INITIAL_OUTREACH:');

if (!isOutreach) return [{ json: ctx }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
if (rows.length > 0) {
  // Already contacted recently -> return nothing, which halts this branch.
  return [];
}
return [{ json: ctx }];

// This workflow runs with binaryMode "separate", so n8n keeps binary payloads
// on disk and binary.data.data is a REFERENCE, not base64. Reading it directly
// sent garbage to the vision model ("Bad request - Provider returned error").
// getBinaryDataBuffer() is the only way that works in both binary modes.
const ctx = $('Resolve Lead Identity').first().json;
const bin = ($input.first().binary || {}).data;
if (!bin) {
  throw new Error('KYC image download produced no binary property - check the WAHA file URL and API key.');
}
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buf.toString('base64');
if (!b64 || b64.length < 100) {
  throw new Error('KYC image decoded to ' + b64.length + ' base64 chars - too small to be a document.');
}
return [{ json: {
  document_base64: b64,
  mime_type: bin.mimeType || 'image/jpeg',
  size_bytes: buf.length,
  chat_id: ctx.sender,
  lead_email: ctx.lead_email,
  lead_name: ctx.lead_name
} }];

// Every node whose success this run is about to claim.
const CLAIMED = [
  { node: 'Send Reply via WAHA HTTP API', what: 'WhatsApp reply to the customer', critical: true },
  { node: 'Log Conversation',             what: 'communication_logs row for the reply', critical: false },
  { node: 'Claim Message Id',             what: 'idempotency claim in processed_messages', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

// 30 Aug 2026: a voice note adds a FOURTH, non-critical claim -- but only on
// runs where the voice branch actually ran. Adding it to CLAIMED unconditionally
// would make check() report 'node did not run on this branch' for every text
// message and turn every text run PARTIAL.
let voiceClaim = null;
try {
  const mt = $('Merge Voice Transcript');
  if (mt && (mt.isExecuted === undefined || mt.isExecuted)) {
    const v = mt.first().json || {};
    voiceClaim = {
      what: 'voice note transcription',
      critical: false,
      ok: v.voice_transcribed === true,
      why: v.voice_transcribed === true ? '' : String(v.voice_drop_reason || 'transcription failed').slice(0, 300),
    };
  }
} catch (e) { voiceClaim = null; }

const results  = CLAIMED.map(check);
if (voiceClaim) results.push(voiceClaim);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
}, pairedItem: { item: 0 } }];

// Make.com used to do this: take a raw inbound enquiry and hand the Master
// Router a lead-shaped object. Make.com is empty now -- every workflow was
// moved into n8n -- so WhatsApp is the live inbound channel and this is where
// the shaping happens.
//
// `Validate & Enrich Input` on the Router accepts `.body`, `.lead`, or a bare
// object, and needs an email OR a phone. We have the phone.
const ctx = $('Resolve Lead Identity').first().json;

const digits = String(ctx.sender_phone || '').replace(/[^0-9]/g, '');
if (!digits) return [];   // nothing the Router could key a lead on

return [{ json: {
  name: ctx.lead_name || ctx.push_name || 'WhatsApp enquiry',
  phone: '+' + digits,
  email: ctx.lead_email || null,
  message: ctx.message || null,
  vehicle_interest: ctx.message || null,
  source: 'whatsapp',
  // Tells the Router the customer is ALREADY in a live thread, so it scores,
  // alerts and syncs but does NOT fire a canned welcome on top of the reply
  // the BDC agent has just sent them.
  origin: 'whatsapp-bdc',
  // The Router must not re-derive the dealership from a phone number.
  tenant_id: $('Tenant Context').first().json.tenant_id,
} }];

// Human Spoke Recently?  — added by the human-handover handoff.
//
// Collapses `Human Reply Check` (0 or 1 row, or 1 error item) into EXACTLY ONE
// item carrying the Resolve Lead Identity context plus a mode. Every node after
// this one runs once per item, so returning anything other than one item would
// multiply the whole reply chain.
//
// THE TWO WINDOWS. Both live here and nowhere else.
//   HARD_SILENCE_MIN  30  — a rep spoke within the last 30 minutes: the bot says
//                           NOTHING. A WhatsApp haggle runs at minutes per turn,
//                           and the failure this fixes ("I can do 78,000 final"
//                           / "ok" / bot quotes its own number) happens inside
//                           one of those turns. 30 minutes also covers the rep
//                           putting the phone down to walk the lot. It does not
//                           strand the customer: by definition a person is on
//                           this thread right now.
//   SUPERVISED_HOURS  12  — from 30 minutes to 12 hours the bot DOES answer,
//                           instantly, but its prompt is told a colleague is
//                           already in this conversation and it must not touch
//                           any number that colleague named. A customer who
//                           writes the next morning is past 12h and gets normal
//                           service; a customer who writes at midnight after a
//                           7pm rep message still gets an instant answer, just a
//                           careful one. Full silence for 12h would be the cure
//                           killing the patient.
//
// FAIL DIRECTION. If the lookup could not be done (Supabase down, malformed
// or=() filter, PostgREST 400) we do NOT know whether a rep is mid-negotiation.
// That degrades to 'supervised', not to 'normal': the customer still gets an
// instant reply, but one that cannot contradict a colleague. Zero rows is a real
// answer, not an error, and gives 'normal'.
const HARD_SILENCE_MIN = 30;
const SUPERVISED_HOURS = 12;

let ctx = {};
try { ctx = $('Resolve Lead Identity').first().json || {}; } catch (e) { ctx = {}; }

const rows = $input.all().map(i => (i && i.json) || {});
const errored = rows.some(r => r.error !== undefined && r.error !== null);
const hit = rows.find(r => r && r.created_at);

let mode = 'normal';
let human_minutes = null;
let last_human_by = '';
let last_human_message = '';

if (hit) {
  const t = new Date(hit.created_at).getTime();
  if (isNaN(t)) {
    mode = 'supervised';
  } else {
    human_minutes = Math.max(0, Math.round((Date.now() - t) / 60000));
    last_human_by = String(hit.sent_by || 'a colleague');
    last_human_message = String(hit.message || '').replace(/\s+/g, ' ').trim().slice(0, 400);
    mode = human_minutes < HARD_SILENCE_MIN ? 'silent'
         : human_minutes < SUPERVISED_HOURS * 60 ? 'supervised'
         : 'normal';
  }
} else if (errored) {
  mode = 'supervised';
}

// The block the agent prompt prepends. Empty unless we are supervising.
let handover_note = '';
if (mode === 'supervised') {
  handover_note =
    'HANDOVER NOTE — READ THIS BEFORE ANSWERING. A human colleague from the dealership is already '
    + 'handling this conversation on this same WhatsApp number'
    + (human_minutes === null
        ? '.'
        : '; their last message to this customer was ' + human_minutes + ' minutes ago'
          + (last_human_message ? ' and it said: "' + last_human_message + '"' : '.'))
    + '\n'
    + 'Do NOT contradict your colleague. Do NOT restate, improve, reduce, re-confirm or withdraw any '
    + 'price, discount, figure, deadline or commitment they have made, and do NOT make a commercial '
    + 'offer of your own in this thread. Answer only the factual part of what the customer just asked '
    + '— stock, specification, availability, timing, policy. If they are asking about price, payment, '
    + 'discount, part-exchange value or anything already being negotiated, say your colleague is '
    + 'looking after that and will come straight back to them, and stop there. Keep it to one or two '
    + 'short lines and do not open a new topic.';
}

return [{ json: {
  ...ctx,
  human_mode: mode,
  human_minutes,
  last_human_by,
  last_human_message,
  handover: mode === 'supervised',
  handover_note,
  human_check_errored: errored
}, pairedItem: { item: 0 } }];

// Prepare Voice Upload
// Validates the WAHA download, applies the duration cap, and normalises the
// binary metadata so Groq accepts the multipart upload.
//
// Deliberately does NOT call this.helpers.getBinaryDataBuffer(): the workflow
// runs with binaryMode "separate", so the audio bytes live outside the item.
// Pulling them into the heap of a 958 MB box buys nothing -- only the binary
// METADATA is needed, and n8n streams the file itself at upload time.
const MAX_SECONDS = 180;

// Duration comes from `Extract Message & Sender`, which read it off
// payload._data.Message.audioMessage.seconds. No webhook reach-back is needed:
// the outreach entry path (`Called by Master Router`) never sets is_voice, so
// this node is unreachable from it.
let ex = {};
try { ex = $('Extract Message & Sender').first().json || {}; } catch (e) { ex = {}; }
const seconds = Number(ex.audio_seconds || 0);

const out = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const binary = item.binary || {};

  let ok = true;
  let reason = '';

  if (json.error !== undefined && json.error !== null) {
    // `Download Voice Note` runs with onError: continueRegularOutput, so a 404
    // after WHATSAPP_FILES_LIFETIME (180s) expiry lands here as data, not a throw.
    ok = false;
    reason = 'waha download failed: ' + String((json.error && (json.error.message || json.error.description)) || json.error).slice(0, 200);
  } else if (!binary.data) {
    ok = false;
    reason = 'waha returned no audio body (file expired, 404, or media was never stored)';
  } else if (seconds > MAX_SECONDS) {
    ok = false;
    reason = 'voice note is ' + seconds + 's, over the ' + MAX_SECONDS + 's cap';
  } else if (!String(binary.data.mimeType || ex.audio_mime || '').toLowerCase().startsWith('audio/')) {
    ok = false;
    reason = 'unsupported mimetype: ' + String(binary.data.mimeType || ex.audio_mime || 'unknown');
  }

  if (ok) {
    // Groq rejects an upload whose filename carries no recognised audio
    // extension. WAHA sets media.filename to null for audio, and n8n then falls
    // back to the URL basename or the literal "data". Force it.
    item.binary.data.fileName = 'voice.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }

  out.push({
    json: {
      voice_ok: ok,
      voice_drop_reason: reason,
      voice_seconds: seconds,
      voice_mime: String(ex.audio_mime || 'audio/ogg; codecs=opus'),
    },
    binary: ok ? item.binary : undefined,
    pairedItem: { item: 0 },
  });
}
return out;

// Merge Voice Transcript
// Single join point for both legs: Groq success/failure, and the give-up leg
// from `Voice Is Usable?` false. It NEVER throws and it always emits exactly
// one item, so the customer is never met with silence because of this branch.
const j = ($input.first() || {}).json || {};

// The Groq HTTP node REPLACES the item, so the pre-flight verdict has to be
// read back from `Prepare Voice Upload` explicitly.
let prep = {};
try { prep = $('Prepare Voice Upload').first().json || {}; } catch (e) { prep = {}; }

let transcript = '';
let language = null;
let reason = String(prep.voice_drop_reason || '');

if (!reason) {
  // We came through Groq.
  if (j.error !== undefined && j.error !== null) {
    reason = 'groq: ' + String((j.error && (j.error.message || j.error.description)) || j.error).slice(0, 200);
  } else {
    transcript = String(j.text ?? '').trim();
    language = j.language ? String(j.language) : null;
    if (!transcript) reason = 'groq returned an empty transcript';
  }
}

const ok = !reason && !!transcript;

// The fallback is an INSTRUCTION to the agent, not a canned string sent to the
// customer -- that is the only way the apology comes back in the customer's own
// language. Same convention as the INITIAL_OUTREACH: prefix that
// `Extract Message & Sender` already injects for router-initiated outreach.
//
// The drop reason is deliberately NOT interpolated into this text. It flows
// downstream into `Reply Eligibility`, whose 73-keyword allowlist is a substring
// match -- an arbitrary Groq error string could contain "model" or "service" and
// silently widen the allowlist for an unknown number.
const NOTE = 'SYSTEM_NOTE: This person sent a WhatsApp voice message and we were not able to turn it into text. Do not guess what they said. Reply briefly, in whatever language they have been writing in, say sorry you missed it, and ask them to write it out or send a shorter recording.';

return [{ json: {
  message: ok ? transcript : NOTE,
  is_voice: true,
  voice_transcribed: ok,
  voice_transcript: ok ? transcript : '',
  voice_language: language,
  voice_seconds: Number(prep.voice_seconds || 0),
  voice_drop_reason: ok ? '' : reason,
}, pairedItem: { item: 0 } }];

/* The WAHA webhook node has authentication:'none'. Resolving the tenant from the
 * session name is only as trustworthy as the claim that the delivery really came
 * from that dealership's WAHA container: anyone who can reach the n8n webhook can
 * name any registered session. The Cloud receiver closes this with an HMAC over
 * the raw body (ops/n8n-whatsapp-cloud/verify-or-refuse.node.js). There is NO
 * schema home for a WAHA webhook secret today -- nexus_channel_secret_reveal() is
 * hard-coded to channel_type='whatsapp_cloud_phone_number_id' -- so this node reads
 * a per-tenant environment variable and REFUSES when it is absent. It never falls
 * back to a shared secret and it never waves the request through. See SCHEMA_GAPS.md
 * gap G1. */
const t = $('Resolve Tenant From WAHA Session').first().json || {};
const slug = String(t.tenant_slug || '');
const envKey = 'WAHA_WEBHOOK_SECRET__' + slug.toUpperCase().replace(/[^A-Z0-9]+/g, '_');
const expected = $env[envKey];
if (!expected) {
  throw new Error(
    'BDC_WAHA_ORIGIN_SECRET_NOT_CONFIGURED: tenant ' + slug + ' has no inbound webhook ' +
    'secret. Set env ' + envKey + ' on the n8n host (interim) or land the channel_secret ' +
    'kind for whatsapp_waha_session (SCHEMA_GAPS G1). Refusing rather than trusting an ' +
    'unauthenticated POST that names a registered session.');
}
const hdrs = $('WAHA Webhook (POST)').first().json.headers || {};
const got = String(hdrs['x-webhook-secret'] || hdrs['X-Webhook-Secret'] || hdrs['x-api-key'] || '');
let ok = got.length === String(expected).length && got.length > 0;
for (let i = 0; i < got.length; i++) ok = ok && (got[i] === String(expected)[i]);
if (!ok) {
  throw new Error('BDC_WAHA_ORIGIN_REFUSED: inbound delivery for tenant ' + slug +
    ' did not present the configured webhook secret. Not processed, not logged.');
}
return $input.all();

/* Outreach path. The caller is another NEXUS workflow (the Master Router), not a
 * customer, so the tenant arrives as a sub-workflow input rather than from a
 * channel identity. That is an INTERNAL trust boundary and it is not the same as
 * trusting a message body -- but it is only as good as the caller, so this node
 * refuses outright when the caller did not name a tenant instead of letting the
 * row fall to nexus_default_tenant_id(). The Master Router export must be checked
 * to confirm it actually passes tenant_id; that has NOT been verified here.
 * settings.callerPolicy is 'workflowsFromSameOwner', which is what keeps a
 * third party from calling this workflow at all. */
const it = $input.first().json || {};
const tid = String(it.tenant_id || (it.lead && it.lead.tenant_id) || '');
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID.test(tid)) {
  throw new Error(
    'BDC_OUTREACH_TENANT_NOT_SUPPLIED: the calling workflow did not pass a tenant_id ' +
    '(got ' + JSON.stringify(tid) + '). NEXUS will not pick a dealership for an outbound ' +
    'WhatsApp message. Pass tenant_id in the Execute Workflow inputs.');
}
return [{ json: Object.assign({}, it, { tenant_id: tid, tenant_slug: String(it.tenant_slug || ''),
  integration_id: String(it.integration_id || ''), tenant_origin: 'master_router_input' }) }];

/* The ONE place the dealership is decided. Every downstream read carries
 * tenant_id=eq.<t>, every write carries tenant_id, and every expression reads it
 * from here -- so there is exactly one node to audit. It passes the original item
 * straight through (Extract Message & Sender still needs item.lead on the outreach
 * path), and adds nothing that came from the customer. */
const it = $input.first().json || {};
let t = null, origin = null;
try { const r = $('Resolve Tenant From WAHA Session').first().json; if (r && r.tenant_id) { t = r; origin = 'waha_session_channel_registry'; } } catch (e) {}
if (!t) { try { const r = $('Require Tenant From Caller').first().json; if (r && r.tenant_id) { t = r; origin = 'master_router_input'; } } catch (e) {} }
if (!t || !t.tenant_id) {
  throw new Error('BDC_TENANT_UNRESOLVED: reached Tenant Context with no dealership. ' +
    'Refusing to continue -- a default tenant is not an answer.');
}
return [{ json: Object.assign({}, it, {
  tenant_id: t.tenant_id,
  tenant_slug: t.tenant_slug || null,
  integration_id: t.integration_id || null,
  waha_session: t.external_identifier || null,
  waha_credential_ref: t.credential_ref || null,
  tenant_origin: origin
}) }];

/* Everything the agent used to have as a literal now comes from per-tenant data,
 * and anything the schema cannot hold becomes a NAMED ABSENCE rather than a
 * borrowed default. Nothing here falls back to Tenant A.
 *
 * tenant_configuration holds brand_name / ai_tone / default_language / currency /
 * timezone. It has NO column for a discount ceiling, an opening band or a make
 * allowlist (SCHEMA_GAPS G3). Until it does, those are read out of the free-form
 * approval_rules jsonb under the key 'bdc_negotiation'; when that key is absent the
 * agent gets NO discount authority at all and is told to hand the number to a human.
 * Quoting list price with no authority to discount is the safe failure. */
const ctx = $('Tenant Context').first().json;
let cfg = {};
try {
  const rows = $('Fetch Tenant Config').all().map(i => i.json).filter(Boolean);
  cfg = rows.find(r => r && r.tenant_id === ctx.tenant_id) || rows[0] || {};
} catch (e) { cfg = {}; }

const brand = (cfg.brand_name && String(cfg.brand_name).trim())
  || (cfg.tenant_name && String(cfg.tenant_name).trim())
  || null;

const rules = (cfg.approval_rules && typeof cfg.approval_rules === 'object') ? cfg.approval_rules : {};
const neg = (rules.bdc_negotiation && typeof rules.bdc_negotiation === 'object') ? rules.bdc_negotiation : null;
const num = v => (typeof v === 'number' && isFinite(v)) ? v : null;

const ceiling = neg ? num(neg.max_discount_pct) : null;
const openLo  = neg ? num(neg.opening_band_pct_min) : null;
const openHi  = neg ? num(neg.opening_band_pct_max) : null;
const makes   = neg && Array.isArray(neg.make_allowlist) ? neg.make_allowlist.map(String).filter(Boolean) : null;

const missing = [];
if (!brand) missing.push('brand_name (tenant_configuration.brand_name is null and tenants.name is empty)');
if (ceiling === null) missing.push('max_discount_pct');
if (openLo === null || openHi === null) missing.push('opening_band_pct_min/max');
if (!makes || !makes.length) missing.push('make_allowlist');

/* WAHA channel for this dealership. The session name HAS a home in the schema
 * (channel_registry.external_identifier). The host and the API key DO NOT
 * (SCHEMA_GAPS G1, G2), so they are read from environment variables keyed by
 * tenant slug and are left NULL with a named reason when absent -- the nodes that
 * actually need them refuse there, so a text-only conversation is not blocked by a
 * missing media host. Nothing falls back to a shared value. */
const SUF = String(ctx.tenant_slug || '').toUpperCase().replace(/[^A-Z0-9]+/g, '_');
let ch = null;
try { ch = ($('Fetch WAHA Channel').all().map(i => i.json).filter(r => r && r.external_identifier))[0] || null; } catch (e) { ch = null; }
const session = ch ? String(ch.external_identifier) : null;
const ref = ch ? String(ch.credential_ref || '') : '';
const keyEnv = ref.startsWith('env:') ? ref.slice(4) : null;
const baseEnv = SUF ? ('WAHA_BASE_URL__' + SUF) : null;
const base = baseEnv && $env[baseEnv] ? String($env[baseEnv]).replace(/\/+$/, '') : null;
const wahaRefusals = [];
if (!session) wahaRefusals.push('BDC_WAHA_SESSION_UNKNOWN: no active whatsapp_waha_session row in channel_registry for this dealership');
if (!base) wahaRefusals.push('BDC_WAHA_HOST_NOT_TENANT_SCOPED: channel_registry has no endpoint column (SCHEMA_GAPS G2); env ' + (baseEnv || '<no slug>') + ' is not set');
if (!keyEnv || !$env[keyEnv]) wahaRefusals.push('BDC_WAHA_CREDENTIAL_UNRESOLVED: credential_ref ' + JSON.stringify(ref) + ' did not resolve to a set environment variable (SCHEMA_GAPS G1)');

return [{ json: Object.assign({}, ctx, { tenant_waha: {
  integration_id: ch ? ch.integration_id : null,
  session: session,
  base_url: base,
  api_key_env: (keyEnv && $env[keyEnv]) ? keyEnv : null,
  base_url_env: baseEnv,
  refusals: wahaRefusals,
  source: 'channel_registry.whatsapp_waha_session scoped to tenant_id'
}, tenant_policy: {
  brand_name: brand,
  brand_state: brand ? 'stated' : 'NOT_STATED',
  ai_tone: cfg.ai_tone || null,
  default_language: cfg.default_language || null,
  currency: cfg.currency || 'AED',
  timezone: cfg.timezone || null,
  max_discount_pct: ceiling,
  opening_band_pct_min: openLo,
  opening_band_pct_max: openHi,
  make_allowlist: makes,
  negotiation_state: (ceiling === null) ? 'NO_AUTHORITY' : 'stated',
  not_stated: missing,
  config_source: 'tenant_configuration via nexus_resolve_tenant_config'
} }) }];
